import numpy as np


class QuantumDataEncoder:
    """Advanced quantum data encoding strategies."""

    def __init__(self, n_qubits):
        self.n_qubits = n_qubits
        self.dim = 2 ** n_qubits

    def _ry(self, theta):
        return np.array([
            [np.cos(theta / 2), -np.sin(theta / 2)],
            [np.sin(theta / 2), np.cos(theta / 2)]
        ], dtype=complex)

    def _rz(self, theta):
        return np.array([
            [np.exp(-1j * theta / 2), 0],
            [0, np.exp(1j * theta / 2)]
        ], dtype=complex)

    def _rx(self, theta):
        return np.array([
            [np.cos(theta / 2), -1j * np.sin(theta / 2)],
            [-1j * np.sin(theta / 2), np.cos(theta / 2)]
        ], dtype=complex)

    def _single_qubit_gate(self, gate, qubit):
        full_op = np.array([[1]], dtype=complex)
        for q in range(self.n_qubits):
            if q == qubit:
                full_op = np.kron(full_op, gate)
            else:
                full_op = np.kron(full_op, np.eye(2, dtype=complex))
        return full_op

    def _apply_cnot(self, state, control, target):
        cnot = np.zeros((self.dim, self.dim), dtype=complex)
        for i in range(self.dim):
            control_bit = (i >> (self.n_qubits - 1 - control)) & 1
            if control_bit == 1:
                j = i ^ (1 << (self.n_qubits - 1 - target))
                cnot[j, i] = 1.0
            else:
                cnot[i, i] = 1.0
        return cnot @ state

    def basis_encoding(self, x):
        """Basis encoding: binary representation of integer."""
        state = np.zeros(self.dim, dtype=complex)
        # TODO: Convert input to binary and set corresponding basis state
        x_int = int(np.clip(x[0], 0, self.dim - 1))
        state[x_int] = 1.0
        return state

    def dense_angle_encoding(self, x):
        """Dense angle encoding: 2 features per qubit using RY and RZ."""
        state = np.zeros(self.dim, dtype=complex)
        state[0] = 1.0

        for q in range(min(self.n_qubits, len(x) // 2)):
            # TODO: Apply RY for first feature, RZ for second
            ry_gate = self._ry(x[2 * q] * np.pi)
            state = self._single_qubit_gate(ry_gate, q) @ state

            rz_gate = self._rz(x[2 * q + 1] * np.pi)
            state = self._single_qubit_gate(rz_gate, q) @ state

        return state

    def tree_tensor_encoding(self, x, depth=2):
        """Tree tensor network encoding with hierarchical entanglement."""
        state = np.zeros(self.dim, dtype=complex)
        state[0] = 1.0

        # TODO: Apply RY rotations
        for q in range(min(self.n_qubits, len(x))):
            ry = self._ry(x[q] * np.pi)
            state = self._single_qubit_gate(ry, q) @ state

        # TODO: Hierarchical entangling (tree structure)
        level_size = self.n_qubits
        stride = 1
        for _ in range(depth):
            for q in range(0, level_size, stride * 2):
                if q + stride < self.n_qubits:
                    state = self._apply_cnot(state, q, q + stride)
            stride *= 2
            level_size //= 2

        return state

    def hamiltonian_encoding(self, x, t=1.0):
        """Hamiltonian evolution encoding: exp(-i * H * t) |0>."""
        state = np.zeros(self.dim, dtype=complex)
        state[0] = 1.0

        # TODO: Build Hamiltonian H = sum(x_i * Z_i) + sum(x_i * x_j * Z_i Z_j)
        H = np.zeros((self.dim, self.dim), dtype=complex)

        # Single-body terms
        for q in range(min(self.n_qubits, len(x))):
            z_op = np.zeros((self.dim, self.dim), dtype=complex)
            for i in range(self.dim):
                bit = (i >> (self.n_qubits - 1 - q)) & 1
                z_op[i, i] = 1.0 if bit == 0 else -1.0
            H += x[q] * z_op

        # Two-body terms
        for q1 in range(min(self.n_qubits, len(x))):
            for q2 in range(q1 + 1, min(self.n_qubits, len(x))):
                zz = np.zeros((self.dim, self.dim), dtype=complex)
                for i in range(self.dim):
                    b1 = (i >> (self.n_qubits - 1 - q1)) & 1
                    b2 = (i >> (self.n_qubits - 1 - q2)) & 1
                    zz[i, i] = 1.0 if (b1 == b2) else -1.0
                H += x[q1] * x[q2] * zz

        # TODO: Apply unitary evolution: exp(-i * H * t)
        eigenvalues, eigenvectors = np.linalg.eigh(H)
        U = eigenvectors @ np.diag(np.exp(-1j * eigenvalues * t)) @ eigenvectors.conj().T

        state = U @ state
        return state

    def compare_encodings(self, x):
        """Compare different encoding strategies."""
        encodings = {
            'basis': self.basis_encoding(x),
            'dense_angle': self.dense_angle_encoding(x),
            'tree_tensor': self.tree_tensor_encoding(x[:self.n_qubits]),
            'hamiltonian': self.hamiltonian_encoding(x[:self.n_qubits])
        }

        results = {}
        for name, state in encodings.items():
            n_nonzero = np.sum(np.abs(state) ** 2 > 1e-10)
            entropy = 0.0
            probs = np.abs(state) ** 2
            probs = probs[probs > 1e-10]
            entropy = -np.sum(probs * np.log2(probs))

            results[name] = {
                'nonzero_amplitudes': int(n_nonzero),
                'shannon_entropy': float(entropy),
                'norm': float(np.linalg.norm(state))
            }

        return results


if __name__ == "__main__":
    np.random.seed(42)
    encoder = QuantumDataEncoder(n_qubits=3)

    x = np.array([0.5, 0.3, 0.7])
    results = encoder.compare_encodings(x)

    for name, metrics in results.items():
        print(f"{name}: nonzero={metrics['nonzero_amplitudes']}, entropy={metrics['shannon_entropy']:.3f}")
